const dTag=x=>{const td=today();return x.status=='Received'?'<span class="tag fw g">Received</span>':x.status=='In transit'?'<span class="tag fw y">In Transit</span>':`<span class="tag fw ${x.due<td?'r':x.due==td?'y':''}">${x.due<td?'Overdue':x.due==td?'Today':fd(x.due)}</span>`};
