/* hide rows that don't fit in each panel (big-screen mode) and say how many more */
function fitLive(){if(view!='live'||innerWidth<=1400)return;$$('#main .lvg>.panel').forEach(p=>{p.querySelectorAll('p.fm').forEach(e=>e.remove());const R=[...p.querySelectorAll('.nrow,.hb,.prio')];R.forEach(r=>r.style.display='');
  const bad=()=>p.scrollHeight>p.clientHeight+1;let k=R.length;if(!bad())return;const m=document.createElement('p');m.className='muted fm';m.style.margin='.3rem 0 0';
  while(k>1&&bad()){R[--k].style.display='none';m.textContent='+'+(R.length-k)+' more';(R[k-1]||p.querySelector('h2')).after(m)}})}
let liveSig='';const sigOf=()=>JSON.stringify([S.deliveries.map(d=>[d.id,d.status,d.due]),S.contracts.map(c=>[c.id,c.stage,c.fit]),S.items.slice(0,3).map(r=>r.uid+r.reqStatus)]);
