setInterval(()=>{if(view!='live'||$('.ov.open')||document.activeElement.matches('input,select,textarea'))return;if(sigOf()!=liveSig){render();return}const u=$('#upd');if(u)u.textContent=new Date().toLocaleTimeString('en-GB')},10000);
