  const list=all.filter(x=>hit(x)&&(F.s=='all'||x.supplier==F.s)&&(F.f=='all'||(F.f=='out'?x.status!='Received':x.status=='Received'))),n=k=>all.filter(x=>lane(x)==k).length;
