  const card=x=>`<div class="dcard"><div class="dtop"><span class="dsup"><i style="background:${supCol(x.supplier)}"></i>${esc(x.supplier)}</span>${dTag(x)}</div><b>${esc(x.items)}</b><div class="muted">${esc(x.contract||'No Job Ref')}</div>${x.stage?`<div class="dst">${esc(x.stage)}${msDots(x)}</div>`:''}<div class="dact">${x.status!='Received'?`<button class="mini pri" ${A('recvD',x.id)}>Received</button>`:''}<button class="mini" ${A('editDel',x.id)}>Edit</button></div></div>`;
  const LN=[['od','Overdue','r'],['td','Due Today','y'],['tr','In Transit','y'],['wk','Next 7 Days',''],['lt','Later',''],['rec','Received','g']];
